void hp_describe_resp_write(htlv_writer_t *w, const hp_describe_resp_t *m)
{
    for (size_t i = 0; i < m->points_count && i < 24; i++) {
        size_t mark = htlv_w_begin(w, 0x01);
        hp_point_def_write(w, &m->points[i]);
        htlv_w_end(w, mark);
    }
}

hp_decode_result_t hp_describe_resp_read(hp_describe_resp_t *m, const uint8_t *p, size_t n)
{
    memset(m, 0, sizeof *m);
    htlv_reader_t r;
    htlv_r_init(&r, p, n);
    uint8_t tag;
    const uint8_t *v;
    size_t vn;
    htlv_result_t res;
    while ((res = htlv_r_next(&r, &tag, &v, &vn)) == HTLV_OK) {
        switch (tag & 0x7F) {
        case 1:
            if (m->points_count >= 24) return HP_DECODE_TOO_LONG;
            {
                hp_decode_result_t sub = hp_point_def_read(&m->points[m->points_count], v, vn);
                if (sub != HP_DECODE_OK) return sub;
            }
            m->points_count++;
            break;
        default:
            if (tag & 0x80) return HP_DECODE_UNSUPPORTED;
            break;
        }
    }
    return res == HTLV_END ? HP_DECODE_OK : HP_DECODE_MALFORMED;
}

