void hp_wifi_scan_resp_write(htlv_writer_t *w, const hp_wifi_scan_resp_t *m)
{
    for (size_t i = 0; i < m->networks_count && i < 20; i++) {
        size_t mark = htlv_w_begin(w, 0x01);
        hp_wifi_net_write(w, &m->networks[i]);
        htlv_w_end(w, mark);
    }
}

hp_decode_result_t hp_wifi_scan_resp_read(hp_wifi_scan_resp_t *m, const uint8_t *p, size_t n)
{
    memset(m, 0, sizeof *m);
    htlv_reader_t r;
    htlv_r_init(&r, p, n);
    uint8_t tag;
    const uint8_t *v;
    size_t vn;
    htlv_result_t res;
    while ((res = htlv_r_next(&r, &tag, &v, &vn)) == HTLV_OK) {
        switch (tag & 0x7F) {
        case 1:
            if (m->networks_count >= 20) return HP_DECODE_TOO_LONG;
            {
                hp_decode_result_t sub = hp_wifi_net_read(&m->networks[m->networks_count], v, vn);
                if (sub != HP_DECODE_OK) return sub;
            }
            m->networks_count++;
            break;
        default:
            if (tag & 0x80) return HP_DECODE_UNSUPPORTED;
            break;
        }
    }
    return res == HTLV_END ? HP_DECODE_OK : HP_DECODE_MALFORMED;
}

