void hp_ota_begin_req_write(htlv_writer_t *w, const hp_ota_begin_req_t *m)
{
    if (m->has_size) {
        htlv_w_u32(w, 0x01, m->size);
    }
    if (m->has_sha256) {
        htlv_w_bytes(w, 0x02, m->sha256, m->sha256_len);
    }
    if (m->has_version) {
        htlv_w_str(w, 0x03, m->version);
    }
    if (m->has_model) {
        htlv_w_u16(w, 0x04, m->model);
    }
}

hp_decode_result_t hp_ota_begin_req_read(hp_ota_begin_req_t *m, const uint8_t *p, size_t n)
{
    memset(m, 0, sizeof *m);
    htlv_reader_t r;
    htlv_r_init(&r, p, n);
    uint8_t tag;
    const uint8_t *v;
    size_t vn;
    htlv_result_t res;
    while ((res = htlv_r_next(&r, &tag, &v, &vn)) == HTLV_OK) {
        switch (tag & 0x7F) {
        case 1:
            if (!htlv_get_u32(v, vn, &m->size)) return HP_DECODE_MALFORMED;
            m->has_size = true;
            break;
        case 2:
            if (vn > 32) return HP_DECODE_TOO_LONG;
            m->sha256 = v;
            m->sha256_len = vn;
            m->has_sha256 = true;
            break;
        case 3:
            if (!htlv_get_str(v, vn, m->version, sizeof m->version)) return HP_DECODE_TOO_LONG;
            m->has_version = true;
            break;
        case 4:
            if (!htlv_get_u16(v, vn, &m->model)) return HP_DECODE_MALFORMED;
            m->has_model = true;
            break;
        default:
            if (tag & 0x80) return HP_DECODE_UNSUPPORTED;
            break;
        }
    }
    return res == HTLV_END ? HP_DECODE_OK : HP_DECODE_MALFORMED;
}

