void hp_log_req_write(htlv_writer_t *w, const hp_log_req_t *m)
{
    if (m->has_level) {
        htlv_w_u8(w, 0x01, m->level);
    }
    if (m->has_tag) {
        htlv_w_str(w, 0x02, m->tag);
    }
    if (m->has_text) {
        htlv_w_str(w, 0x03, m->text);
    }
    if (m->has_ts_ms) {
        htlv_w_u64(w, 0x04, m->ts_ms);
    }
}

hp_decode_result_t hp_log_req_read(hp_log_req_t *m, const uint8_t *p, size_t n)
{
    memset(m, 0, sizeof *m);
    htlv_reader_t r;
    htlv_r_init(&r, p, n);
    uint8_t tag;
    const uint8_t *v;
    size_t vn;
    htlv_result_t res;
    while ((res = htlv_r_next(&r, &tag, &v, &vn)) == HTLV_OK) {
        switch (tag & 0x7F) {
        case 1:
            if (!htlv_get_u8(v, vn, &m->level)) return HP_DECODE_MALFORMED;
            m->has_level = true;
            break;
        case 2:
            if (!htlv_get_str(v, vn, m->tag, sizeof m->tag)) return HP_DECODE_TOO_LONG;
            m->has_tag = true;
            break;
        case 3:
            if (!htlv_get_str(v, vn, m->text, sizeof m->text)) return HP_DECODE_TOO_LONG;
            m->has_text = true;
            break;
        case 4:
            if (!htlv_get_u64(v, vn, &m->ts_ms)) return HP_DECODE_MALFORMED;
            m->has_ts_ms = true;
            break;
        default:
            if (tag & 0x80) return HP_DECODE_UNSUPPORTED;
            break;
        }
    }
    return res == HTLV_END ? HP_DECODE_OK : HP_DECODE_MALFORMED;
}

